 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full-width / full-height uniform lines are the separators.
    sep_rows = {r for r, row in enumerate(grid) if len(set(row)) == 1}
    sep_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}

    def spans(n, cuts):
        out, start = [], 0
        for i in range(n):
            if i in cuts:
                if start < i:
                    out.append((start, i))
                start = i + 1
        if start < n:
            out.append((start, n))
        return out

    rs, cs = spans(h, sep_rows), spans(w, sep_cols)
    # The separator color is uniform across separator lines. The most common
    # non-separator color inside the panels is the panel background.
    sep_colors = [grid[r][0] for r in sep_rows]
    sep_colors += [grid[0][c] for c in sep_cols]
    sep = max(set(sep_colors), key=sep_colors.count) if sep_colors else None
    from collections import Counter
    counts = Counter(grid[r][c] for a,b in rs for r in range(a,b)
                     for x,y in cs for c in range(x,y)
                     if grid[r][c] != sep)
    bg = counts.most_common(1)[0][0]
    scores = [[sum(grid[r][c] != bg and grid[r][c] != sep
                   for r in range(a,b) for c in range(x,y))
               for x,y in cs] for a,b in rs]
    best = max(max(row) for row in scores)
    return [[int(v == best) for v in row] for row in scores]
